mockups.css:
:root {
  --radius: 0.625rem;
  --background: oklch(0.97 0.015 95);
  --card: oklch(0.985 0.01 95);
  --foreground: oklch(0.22 0.02 255);
  --primary: oklch(0.32 0.05 260);
  --primary-foreground: oklch(0.97 0.015 95);
  --secondary: oklch(0.94 0.018 95);
  --muted: oklch(0.94 0.018 95);
  --muted-foreground: oklch(0.52 0.03 255);
  --accent: oklch(0.93 0.02 95);
  --border: oklch(0.88 0.02 95);
  --destructive: oklch(0.58 0.22 27);
}
* { box-sizing: border-box; }
body { background: var(--background); color: var(--foreground);
  font: 14px/1.5 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; margin: 0; }
.page { padding: 24px; max-width: 1100px; margin: 0 auto; }
h1 { font-size: 22px; font-weight: 600; margin: 0 0 4px; }
h2 { font-size: 15px; font-weight: 600; margin: 0 0 12px; }
.sub { color: var(--muted-foreground); font-size: 13px; margin: 0 0 20px; }
.btn { border: 1px solid var(--border); background: var(--card); color: var(--foreground);
  border-radius: var(--radius); padding: 8px 14px; font-size: 13px; cursor: pointer; }
.btn-primary { background: var(--primary); color: var(--primary-foreground); border-color: var(--primary); }
.btn-ghost { border-color: transparent; background: transparent; }
.btn-icon { padding: 6px 8px; }
.badge { display: inline-flex; align-items: center; justify-content: center;
  min-width: 22px; height: 22px; padding: 0 6px; border-radius: 999px;
  background: var(--secondary); color: var(--foreground); font-size: 12px; font-weight: 600; }
.card { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; }
.row { display: flex; align-items: center; gap: 10px; }
.between { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.muted { color: var(--muted-foreground); }
.tnum { font-variant-numeric: tabular-nums; }
.stack { display: flex; flex-direction: column; gap: 16px; }
.split { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; align-items: start; }
.variant { border: 1px dashed var(--border); border-radius: var(--radius); padding: 16px; background: var(--card); }
.variant h3 { font-size: 13px; font-weight: 600; margin: 0 0 4px; }
.variant .why { font-size: 12px; color: var(--muted-foreground); margin: 0 0 14px; }
.unit { background: var(--secondary); border: 1px solid var(--border); border-radius: 6px;
  display: flex; align-items: center; justify-content: center; font-size: 11px;
  color: var(--muted-foreground); font-variant-numeric: tabular-nums; cursor: pointer; }
.unit:hover { border-color: var(--primary); }
.plan { display: flex; gap: 4px; align-items: flex-start; }
.planwrap { padding: 14px; background: var(--background); border: 1px solid var(--border);
  border-radius: var(--radius); overflow-x: auto; }
.label { font-size: 12px; color: var(--muted-foreground); margin: 0 0 6px; }
.sidebar { border-left: 1px solid var(--border); background: var(--card); padding: 20px; width: 340px; }
.field { display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 8px 0; border-bottom: 1px solid var(--border); }
.field:last-child { border-bottom: 0; }
.stepper { display: flex; align-items: center; gap: 8px; }
.stepper .val { min-width: 46px; text-align: center; font-variant-numeric: tabular-nums; font-weight: 600; }
.section { font-size: 11px; text-transform: uppercase; letter-spacing: .06em;
  color: var(--muted-foreground); margin: 18px 0 6px; }
.input { border: 1px solid var(--border); border-radius: 8px; padding: 6px 10px; width: 68px;
  font-variant-numeric: tabular-nums; background: var(--card); }
.price { font-weight: 600; font-variant-numeric: tabular-nums; }
.pill { border: 1px solid var(--border); border-radius: 999px; padding: 4px 10px; font-size: 12px; background: var(--card); }
.pill-active { border-color: var(--primary); background: var(--accent); }
.note { font-size: 12px; color: var(--muted-foreground); }
.menu { border: 1px solid var(--border); border-radius: var(--radius); background: var(--card);
  padding: 6px; width: 250px; box-shadow: 0 8px 24px oklch(0.22 0.02 255 / 0.10); }
.menu button { display: block; width: 100%; text-align: left; border: 0; background: transparent;
  padding: 9px 10px; border-radius: 8px; font-size: 13px; cursor: pointer; color: var(--foreground); }
.menu button:hover { background: var(--accent); }

